// logon.js — Windows 7 欢迎屏幕：开机动画之后、地图之前。单个本地账户，点头像登录。
// 图片取自原版 Windows 7（LogonUI 背景、头像框、用户头像、轻松访问与关机按钮），以 data URI 内嵌。
(function () {
  'use strict';
  var NAME = 'Brian Miller';
  var st = document.createElement('style'); st.textContent = "#logon{position:fixed;inset:0;z-index:2900000;background:#1a63c6 url(data:image/jpeg;base64,) center/cover no-repeat;font-family:\"Segoe UI\",\"Microsoft YaHei\",\"\u5fae\u8f6f\u96c5\u9ed1\",Tahoma,sans-serif;color:#fff;user-select:none;overflow:hidden;cursor:default}\n#logon[hidden]{display:none}\n#logon .shade{position:absolute;inset:0;background:#000;opacity:0;pointer-events:none;transition:opacity .6s}\n#logon.out .shade{opacity:1}\n#logon .txt{text-shadow:0 0 6px rgba(0,0,0,.55),0 1px 2px rgba(0,0,0,.6)}\n#lu-list{position:absolute;left:0;right:0;top:calc(50% - 70px);display:flex;justify-content:center;gap:30px}\n#lu-list[hidden],#lu-wel[hidden]{display:none}\n.lu-t{width:120px;text-align:center;outline:none}\n.lu-t .fr{position:relative;width:82px;height:81px;margin:0 auto;border-radius:6px}\n.lu-t .fr i{position:absolute;left:10px;top:7px;width:63px;height:63px;background:url(data:image/png;base64,) 0 0/63px 63px}\n.lu-t .fr b{position:absolute;inset:0;background:url(data:image/png;base64,) 0 0/82px 81px no-repeat}\n.lu-t:hover .fr b,.lu-t:focus .fr b{filter:brightness(1.12)}\n.lu-t .nm{margin-top:7px;font-size:12px;line-height:15px}\n#lu-wel{position:absolute;left:0;right:0;top:calc(50% - 22px);display:flex;justify-content:center;align-items:center;gap:12px;font-size:36px;font-weight:300;line-height:44px}\n#lu-wel .spin{width:32px;height:32px;background:url(cursors/busy_00.png) center/32px 32px no-repeat}\n#lu-ease{position:absolute;left:30px;bottom:30px;width:46px;height:36px;background:url(data:image/png;base64,)}\n#lu-off{position:absolute;right:28px;bottom:30px;width:69px;height:36px;background:url(data:image/png;base64,)}\n#lu-ease:hover,#lu-off:hover{filter:brightness(1.15)}\n#lu-logo{position:absolute;left:0;right:0;bottom:26px;display:flex;justify-content:center;align-items:flex-end;pointer-events:none}\n#lu-logo img{display:block;width:169px;height:42px}\n#lu-logo span{font-size:17px;line-height:20px;margin:0 0 9px 5px;font-weight:300;color:rgba(255,255,255,.92)}"; document.head.appendChild(st);
  var Z = function (zh, en) { return '<span class="zh">' + zh + '</span><span class="bi"> </span><span class="en">' + en + '</span>'; };
  var el = document.createElement('div'); el.id = 'logon';
  el.innerHTML =
    '<div id="lu-list"><div class="lu-t" tabindex="0"><div class="fr"><i></i><b></b></div><div class="nm txt">' + NAME + '</div></div></div>' +
    '<div id="lu-wel" class="txt" hidden><span class="spin"></span><span>' + Z('欢迎', 'Welcome') + '</span></div>' +
    '<a id="lu-ease" title="轻松访问 Ease of Access"></a>' +
    '<div id="lu-logo"><img src="data:image/png;base64," alt="Windows 7"><span class="txt">' + Z('旗舰版', 'Ultimate') + '</span></div>' +
    '<a id="lu-off" title="关机 Shut down"></a><div class="shade"></div>';
  document.body.appendChild(el);
  var $ = function (s) { return el.querySelector(s); }, spinT = null, f = 0, busy = false;
  function spin(on) {
    clearInterval(spinT);
    if (on) spinT = setInterval(function () { f = (f + 1) % 18; $('#lu-wel .spin').style.backgroundImage = 'url(cursors/busy_' + (f < 10 ? '0' : '') + f + '.png)'; }, 50);
  }
  function login() {
    if (busy) return; busy = true;
    $('#lu-list').hidden = true; $('#lu-wel').hidden = false; spin(true);
    setTimeout(function () { el.classList.add('out'); }, 2200);
    setTimeout(function () { spin(false); el.hidden = true; document.body.classList.remove('fna-logon'); if (window.onResize) try { onResize(); } catch (e) {} }, 2900);
  }
  el.addEventListener('click', function (e) { if (e.target.closest('.lu-t')) login(); });
  el.addEventListener('keydown', function (e) { if (e.key === 'Enter' && e.target.closest('.lu-t')) login(); });
  window.LOGON = { focus: function () { var t = $('.lu-t'); if (t) t.focus(); } };
})();
